<?php
declare(strict_types=1);
require_once __DIR__.'/bootstrap.php';require_method('GET');$u=current_user();
$ownerWhere=$u['role']==='MEMBER'?' AND c.created_by=?':'';$params=[$u['tenant_id']];if($ownerWhere)$params[]=$u['id'];
$sql="SELECT g.id,g.name,g.subject,g.accountCount,g.recipients,g.sent,g.failed,g.pending,g.createdAt,g.completedAt,CASE WHEN g.pending>0 AND g.runningCount>0 THEN 'RUNNING' WHEN g.pending>0 AND g.pausedCount>0 THEN 'PAUSED' WHEN g.pending>0 THEN 'QUEUED' WHEN g.sent=0 AND g.failed>0 THEN 'FAILED' ELSE 'COMPLETED' END status,(SELECT COUNT(DISTINCT r.lead_id) FROM campaign_recipients r JOIN campaigns c2 ON c2.tenant_id=r.tenant_id AND c2.id=r.campaign_id JOIN leads l ON l.tenant_id=r.tenant_id AND l.id=r.lead_id WHERE c2.tenant_id=? AND c2.batch_group_id=g.id AND l.status='BOUNCED') suppressed FROM (SELECT c.batch_group_id id,MIN(c.name) name,MIN(c.subject) subject,COUNT(*) accountCount,SUM(c.total_recipients) recipients,SUM(c.sent_count) sent,SUM(c.failed_count) failed,SUM(c.pending_count) pending,SUM(c.status='RUNNING') runningCount,SUM(c.status='PAUSED') pausedCount,MIN(c.created_at) createdAt,MAX(c.completed_at) completedAt FROM campaigns c WHERE c.tenant_id=? AND c.batch_group_id IS NOT NULL{$ownerWhere} GROUP BY c.batch_group_id HAVING COUNT(*)>1 ORDER BY MIN(c.created_at) DESC LIMIT 20) g";
$s=db()->prepare($sql);$s->execute([$u['tenant_id'],...$params]);respond($s->fetchAll());
